export function projectCoordsDO(lon: number, lat: number): [number, number] {
  const p = DO_PROJECTION;
  const x = ((lon - p.minLon) / (p.maxLon - p.minLon)) * p.width;
  const y = p.height - ((lat - p.minLat) / (p.maxLat - p.minLat)) * p.height;
  return [x, y];
}
